public ChunkSubmissionView submitChunks(long taskId, SubmitChunksRequest request) {
    List<ChunkDigestEntry> sorted = request.chunks().stream().sorted(comparingInt(index)).toList();
    String fingerprint = join("|", "task.chunks", taskId, request.effectiveComplete(), sha256Hex(canonical(sorted)));
    return idempotency.execute(request.requestId(), "task.chunks", fingerprint, () -> {
        RolloutTask snapshot = taskRepository.findById(taskId).orElseThrow(404);
        ReleaseOrder order = releaseRepository.findByIdForUpdate(snapshot.releaseId()).orElseThrow(404);
        RolloutTask task = taskRepository.findByIdForUpdate(taskId).orElseThrow(404);
        Manifest manifest = manifestRepository.findByReleaseId(task.releaseId())
            .orElseThrow(() -> conflict("MANIFEST_NOT_FOUND", "发布单未登记分片清单，不能接收分片"));
        if (task.status() != PENDING) switch → 409s
        // validate request entries
        validate formats: each digest isSha256Hex else 422 CHUNK_DIGEST_FORMAT
        index range: <0 or >= chunkCount → 422 CHUNK_INDEX_OUT_OF_RANGE (actual, required 0..n-1)
        within-request duplicates: sorted, if any adjacent equal index → 422 CHUNK_DUPLICATE_INDEX (request itself invalid, no state change)
        // received
        List<ChunkReceipt> received = chunkReceiptRepository.findByTaskAndAttempt(taskId, task.attempt());
        Set<Integer> receivedIndexes = ...
        List<ChunkDigestEntry> duplicates = sorted where index in receivedIndexes
        if (!duplicates.isEmpty()) {
            // 重复 → INTEGRITY_FAILED（提交顺序裁决：后到重复判负）
            IntegrityRecord record inserted (reason CHUNK_DUPLICATE, receivedCount=received.size(), computed null)
            taskRepository.transitionFromPending(taskId, INTEGRITY_FAILED)
            return view(task, INTEGRITY_FAILED, accepted 0, received.size(), detail "重复序号: x")
        }
        // insert new receipts
        String now = UtcTimes.now(clock);
        for entry: chunkReceiptRepository.insert(taskId, attempt, releaseId, order.toVersion(), index, digest, now)
        int receivedCount = received.size() + sorted.size();
        // verify?
        if (request.effectiveComplete() || receivedCount == manifest.chunkCount()) {
            if (receivedCount < manifest.chunkCount()) {
                record(CHUNK_MISSING, receivedCount, computed null); transition INTEGRITY_FAILED;
                return view(..., missingCount = chunkCount - receivedCount, detail "缺失 N 个分片，要求 M")
            }
            // full set: build map index→digest
            Map<Integer,String> byIndex = received + new
            List<String> inOrder = 0..n-1 map
            for i: if !inOrder[i].equals(manifest.chunkDigests().get(i)) → CHUNK_DIGEST_MISMATCH detail "分片 i 摘要不匹配，要求 X 实际 Y"; record; transition; return
            String computed = Digests.aggregate(inOrder);
            if (!computed.equals(manifest.packageDigest())) → PACKAGE_DIGEST_MISMATCH; record(computed); transition; return
            // success
            record(INSTALLABLE, null, receivedCount, computed); transition INSTALLABLE; return view(result INSTALLABLE)
        }
        return view(PENDING, result null, acceptedCount sorted.size(), receivedCount, missing)
    }, ChunkSubmissionView.class);
}
